cat > $P/firstdiff.mjs <<'MORPH_FIRSTDIFF_EOF'
// MorphV2 first-difference locator: reads a vitest log and, for every failed comparison whose two
// sides vitest printed in full ("Expected: ..." / "Received: ..." lines, or a "- Expected" / "+ Received"
// diff block), prints where the two first differ, with 40 chars of context on each side. The assertion
// line itself is cut at truncateThreshold, so a one-word difference deep in a long string reads as two
// identical sides (P9b, output-directive-judge: three retries on "the file" / "a file").
// Inlined into the acceptances by decks/tools/build.py (from P9c on).
//   node firstdiff.mjs <vitest log>
import fs from "node:fs";

const lines = fs.readFileSync(process.argv[2], "utf8").split("\n");
const pairs = [];
for (let i = 0; i < lines.length; i++) {
  if (lines[i].startsWith("Expected: ") && (lines[i + 1] ?? "").startsWith("Received: ")) {
    pairs.push([lines[i].slice(10), lines[i + 1].slice(10)]);
    continue;
  }
  if (lines[i] !== "- Expected" || lines[i + 1] !== "+ Received") continue;
  // the diff block: "  x" both sides, "- x" expected only, "+ x" received only, "" an empty common line;
  // it ends at the source pointer " ❯ ..." or a rule line
  const e = [], r = [];
  let j = i + 3;
  for (; j < lines.length && !lines[j].startsWith(" ❯") && !lines[j].startsWith("⎯"); j++) {
    const l = lines[j];
    if (l.startsWith("-")) e.push(l.slice(2));
    else if (l.startsWith("+")) r.push(l.slice(2));
    else { e.push(l.slice(2)); r.push(l.slice(2)); }
  }
  while (e.length && r.length && e[e.length - 1] === "" && r[r.length - 1] === "") { e.pop(); r.pop(); }
  pairs.push([e.join("\n"), r.join("\n")]);
  i = j;
}
let shown = 0;
for (const [e, r] of pairs) {
  if (e === r || shown >= 6) continue;
  let k = 0;
  while (k < e.length && k < r.length && e[k] === r[k]) k++;
  const line = e.slice(0, k).split("\n").length;
  const at = (s) => JSON.stringify((k > 40 ? "..." : "") + s.slice(Math.max(0, k - 40), k + 40));
  console.log(`first difference at char ${k} (line ${line}) of ${e.length}/${r.length}: expected ${at(e)} received ${at(r)}`);
  shown++;
}
MORPH_FIRSTDIFF_EOF
cat > $P/select-cards.probe.ts <<'MORPH_PROBE_EOF'
// P20 probe for select-cards by docs/TASK_P20_rerun.md §2.2 (src/planner/selectCards.ts) — the plan cut down to the
// cards of `--only`, ordered again (issue #11). Record Select Cards examples 1-4 on tests/fixtures/planner/subset.plan.json,
// then rows.
import { test, expect } from "vitest";
import { selectCards } from "../../src/planner/selectCards.js";
import type { SelectResult } from "../../src/planner/selectCards.js";
import type { Plan } from "../../src/planner/types.js";
import { fixtureJson } from "../../tests/helpers.js";

const fresh = (): Plan => fixtureJson("planner/subset.plan.json") as Plan;
const ids = (r: SelectResult): unknown => (r.ok ? [r.plan.cards.map((c) => c.customId), r.plan.generations, r.plan.externalDependsOn] : r.error);

test("Select Cards example 1: a kept card's dropped dependency becomes external", () => {
  const plan = fresh();
  const r = selectCards(plan, ["d", "c"]);
  expect(ids(r)).toStrictEqual([["c", "d"], [["c"], ["d"]], { c: ["a"], d: ["b"] }]);
  expect(r.ok ? [r.plan.spec, r.plan.components] : null).toStrictEqual(["s.yaml", ["k"]]);
  expect(r.ok ? [r.plan.cards[0] === plan.cards[3], r.plan.cards[1] === plan.cards[4]] : null).toStrictEqual([true, true]);
});

test("Select Cards example 2: generations among the kept cards; an outside dependency stays external", () => {
  expect(ids(selectCards(fresh(), ["e", "b", "a"]))).toStrictEqual([["a", "e", "b"], [["a", "e"], ["b"]], { e: ["outside"] }]);
});

test("Select Cards example 3: unknown ids, in only's order", () => {
  expect(selectCards(fresh(), ["zz", "c", "y.1"])).toStrictEqual({ ok: false, error: "--only names cards the plan does not have: zz, y.1" });
});

test("Select Cards example 4: every card kept gives the plan back", () => {
  expect(selectCards(fresh(), ["d", "c", "b", "e", "a"])).toStrictEqual({ ok: true, plan: fresh() });
});

test("row: the plan is not changed; one unknown id; a single card", () => {
  const plan = fresh();
  selectCards(plan, ["d"]);
  selectCards(plan, ["b", "q"]);
  expect(plan).toStrictEqual(fresh());
  expect(selectCards(plan, ["b", "q"])).toStrictEqual({ ok: false, error: "--only names cards the plan does not have: q" });
